const e="pianotalents-milan",d=2025,t="Built from the English rules of the XIV PianoTalents International Competition 2025. The rules print a bank account (IBAN, BIC) and a PayPal address for payment; they are not copied, only the payment method in words. No judging criteria or marks are printed.",n={Title:"PianoTalents International Competition: Rules",Subtitle:"Rules of the PianoTalents International Piano Competition for pianists aged 5 to 17, organised by the PianoFriends Association in Milan.",NoticeTitle:"Please Read Before Registering",Notice:"Apply online by {{RegistrationDeadline}} with the application form and your video link, and pay the registration fee for the video selection ({{VideoFee}}).",Notes:["First round results: by {{FirstRoundResults}}.","Competition dates: {{EventDates}}."],Sections:[{Key:"general",Title:"General Rules",Items:["The PianoFriends Association holds the PianoTalents International Competition at {{Venue}}.","The competition has three rounds: First Round Online (video), Second Round Live and the Final.","The Second Round Live is held in the Hall of Honor. Only up to 10 candidates in each category are admitted.","The Final is held in the same hall. Only the candidate awarded the first absolute prize in each category is admitted.","In the Final the Jury chooses the pieces to be played from the programme of the Second Round.","The programme in each category is free. Each candidate must give the composer, title and duration of every chosen piece on the registration form, for both rounds.","The programme of the Second Round must be different from the programme of the First Round.","The maximum duration of the programme is 8 minutes in category A, 12 minutes in category B, 16 minutes in category C and 20 minutes in category D, in both the First Round and the Second Round."]},{Key:"eligibility",Title:"Who Can Enter",Items:["Pianists of all nationalities between the ages of 5 and 17 are admitted.","Category A is for ages 5 to 7, category B for ages 8 to 10, category C for ages 11 to 13 and category D for ages 14 to 17.","A candidate may apply in a higher-aged category if, according to their preparation, they think it appropriate.","A candidate cannot apply to more than one category.","Winners of the first absolute prize in earlier editions cannot apply again to the same category, only to a higher-aged category.","Every candidate must present a release signed by a parent or guardian that allows the Secretariat to process personal data, including sharing photographic, audio and video material. The release form is on the website with the other application materials."]},{Key:"registration",Title:"How to Register",Items:["Apply by filling in the application form on the PianoFriends website by {{RegistrationDeadline}}.","A request sent after the deadline may exceptionally be accepted at the unappealable judgement of the Artistic Director.","At the time of application, attach the link of the video of the performance for the First Round.","Upload the video preferably to YouTube in unlisted mode, or to a similar platform that gives direct access through a single link.","Give a single video file in 1080 HD format in landscape view. Only one link may be given, but it may show more than one piece recorded at different times.","Record each piece with one fixed camera. No editing or cutting during a piece is allowed.","The video must have been recorded no more than 12 months before the application.",'Pay by bank transfer (net of bank charges) to the registered account of the PianoFriends Association, or by PayPal. The payment reference must be "Contribute PT2025", the candidate surname and the category.',"If the due contributions are not paid, the application is not valid."]},{Key:"fees",Title:"Registration Fees",Items:["Registration fee for the video selection: {{VideoFee}}.","Registration fee for candidates admitted to the Second Round: {{SecondRoundFee}}.","The participation fee is not refunded, except if the competition is cancelled."]},{Key:"dates",Title:"Dates",Items:["Competition dates: {{EventDates}}.","Last date to apply: {{RegistrationDeadline}}.","The results of the First Round are published as final rankings on the PianoFriends website by {{FirstRoundResults}}.","The Final and the Super Prize assignment take place on {{FinalDate}}."]},{Key:"venue",Title:"Venue",Items:["The Second Round and the Final are held at {{Venue}}."]},{Key:"prizes",Title:"Scholarships and Prizes",Items:["Each category has a first absolute prize, a first prize, a second prize and a third prize: {{Scholarships}}.","The first absolute prize winners of each category take part in the Final for the Super Prize ({{SuperPrize}}).","The president of Fondazione Societa dei Concerti and the president of the Cesar Franck International Piano Competition of Brussels each choose one pianist from the first absolute winners to invite to their concert season.","Scholarships are paid by {{ScholarshipPaymentDate}}.","Prize winners promise to use in future the title actually awarded by the Jury. Any abuse is prosecuted according to the law."]},{Key:"judging",Title:"Jury",Items:["The Jury is made up of eminent artists of Italian and foreign nationality.","Jury members may present their own students by telling the secretariat at the start of the competition. They then do not vote on their own students.","The Jury may decide not to award prizes if it thinks no candidate is worthy."]},{Key:"complaints",Title:"Decisions",Items:["The decisions of the Jury are unappealable."]},{Key:"conduct",Title:"Recording and Broadcasting",Items:["For radio or television productions, or audio and video recordings of the rehearsals, the competition and the prize-giving concert, candidates have no right to make any claim or request against the production and broadcasting bodies."]},{Key:"other",Title:"Other Conditions",Items:["Registering for the competition means unconditional acceptance of the regulations and of the right of the Artistic and Organizational Direction to change them.","In any dispute the regulations in Italian and Italian law apply. The court of Milan has jurisdiction."]}],Documents:[{Title:"PianoTalents 2025 rules (English)",Url:"https://www.pianofriends.eu/wp-content/uploads/2025/01/2025_PTC_EngRules.pdf"}]},o=[],i=[{AgeGroup:"A Category (5-7)",Source:"PianoTalents 2025 Rules clause 4",Sections:{About:null,TimeAndFormat:["Free programme of up to 8 minutes in the First Round (video) and in the Second Round (live, with a different programme)."],Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Free programme of up to 8 minutes in the First Round (video) and in the Second Round (live, with a different programme).`},{AgeGroup:"B Category (8-10)",Source:"PianoTalents 2025 Rules clause 4",Sections:{About:null,TimeAndFormat:["Free programme of up to 12 minutes in the First Round (video) and in the Second Round (live, with a different programme)."],Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Free programme of up to 12 minutes in the First Round (video) and in the Second Round (live, with a different programme).`},{AgeGroup:"C Category (11-13)",Source:"PianoTalents 2025 Rules clause 4",Sections:{About:null,TimeAndFormat:["Free programme of up to 16 minutes in the First Round (video) and in the Second Round (live, with a different programme)."],Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Free programme of up to 16 minutes in the First Round (video) and in the Second Round (live, with a different programme).`},{AgeGroup:"D Category (14-17)",Source:"PianoTalents 2025 Rules clause 4",Sections:{About:null,TimeAndFormat:["Free programme of up to 20 minutes in the First Round (video) and in the Second Round (live, with a different programme)."],Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Free programme of up to 20 minutes in the First Round (video) and in the Second Round (live, with a different programme).`}],a=[{Title:"Piano",Source:"PianoTalents 2025 Rules clauses 3 and 4",Sections:{About:["Piano competition in three rounds: online video, live second round and final."],TimeAndFormat:["The Final is made of pieces chosen by the Jury from the programme of the Second Round."],Rules:["Give composer, title and duration of every piece on the registration form for both rounds."],Allowed:null,NotAllowed:null,Judging:null,Points:["No marks or judging criteria are printed in the rules."],Notes:null},Markdown:`## About this competition
- Piano competition in three rounds: online video, live second round and final.

## Time and format
- The Final is made of pieces chosen by the Jury from the programme of the Second Round.

## Rules
- Give composer, title and duration of every piece on the registration form for both rounds.

## Points
- No marks or judging criteria are printed in the rules.`}],r=[],s=[{Key:"EventDates",Kind:"date",Label:"Competition dates",Value:"5-8 June 2025",Source:"PianoTalents 2025 Rules clause 1"},{Key:"FinalDate",Kind:"date",Label:"Final and Super Prize date",Value:"2025-06-08",Source:"PianoTalents 2025 Rules clause 6"},{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to apply",Value:"2025-04-20",Source:"PianoTalents 2025 Rules clause 9"},{Key:"FirstRoundResults",Kind:"date",Label:"First round results by",Value:"2025-05-01",Source:"PianoTalents 2025 Rules clause 11"},{Key:"ScholarshipPaymentDate",Kind:"date",Label:"Scholarships paid by",Value:"2025-07-15",Source:"PianoTalents 2025 Rules clause 5"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"Casa di Riposo Fondazione G. Verdi (Casa Verdi), Hall of Honor",Address:"Milan",City:"Milan, Italy",MapUrl:"",Directions:""},Source:"PianoTalents 2025 Rules clauses 1 and 3"},{Key:"VideoFee",Kind:"fee",Label:"Video selection fee",Value:"EUR 30 for categories A-B; EUR 50 for categories C-D",Source:"PianoTalents 2025 Rules clause 8"},{Key:"SecondRoundFee",Kind:"fee",Label:"Second round fee",Value:"EUR 50 for categories A-B; EUR 70 for categories C-D",Source:"PianoTalents 2025 Rules clause 8"},{Key:"Scholarships",Kind:"prize",Label:"Scholarships by category",Value:"A: first absolute EUR 300, first/second/third EUR 100 each. B: EUR 500, EUR 200 each. C: EUR 700, EUR 250 each. D: EUR 900, EUR 300 each",Source:"PianoTalents 2025 Rules clause 5"},{Key:"SuperPrize",Kind:"prize",Label:"Super Prize",Value:"EUR 1,200",Source:"PianoTalents 2025 Rules clause 6"},{Key:"OrganiserWebsite",Kind:"link",Label:"Organiser website and application form",Value:"https://www.pianofriends.eu",Source:"PianoTalents 2025 Rules clause 9"}],l=[{Claim:"All clauses 1-19 of the 2025 rules captured.",SourceType:"Primary - the event's own rules document",Source:"PianoTalents 2025 Rules",Url:"https://www.pianofriends.eu/wp-content/uploads/2025/01/2025_PTC_EngRules.pdf"}],u={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:o,AgeGroups:i,Competitions:a,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{i as AgeGroups,r as CompetitionAgeGroups,a as Competitions,l as Evidence,t as Note,n as Page,o as ParticipantTypes,e as TemplateKey,s as Variables,d as Year,u as default};
